def find_and_complete_frames(grid):
    """Find and complete rectangular/square frames"""
    H, W = len(grid), len(grid[0])
    output = [[0]*W for _ in range(H)]

    # Find all potential rectangular bounding boxes
    rectangles = []

    for top in range(H):
        for left in range(W):
            for height in range(4, min(7, H-top+1)):
                for width in range(4, min(7, W-left+1)):
                    bot, right = top + height - 1, left + width - 1

                    # Check if this looks like a frame: has 8s on edges
                    top_edge_has_8 = any(grid[top][c] == 8 for c in range(left, right+1))
                    bot_edge_has_8 = any(grid[bot][c] == 8 for c in range(left, right+1))
                    left_edge_has_8 = any(grid[r][left] == 8 for r in range(top, bot+1))
                    right_edge_has_8 = any(grid[r][right] == 8 for r in range(top, bot+1))

                    edge_score = sum([top_edge_has_8, bot_edge_has_8, left_edge_has_8, right_edge_has_8])

                    # If at least one edge has 8s, consider it a candidate
                    if edge_score >= 1:
                        rectangles.append((top, left, bot, right, edge_score))

    # Group overlapping rectangles into larger ones
    from collections import defaultdict

    # Group by starting position
    groups = defaultdict(list)
    for rect in rectangles:
        key = (rect[0], rect[1])
        groups[key].append(rect)

    # For each group, find the merged bounding box
    final_rects = set()

    for key, rects in groups.items():
        if len(rects) >= 2:  # Multiple candidates overlap
            t = min(r[0] for r in rects)
            l = min(r[1] for r in rects)
            b = max(r[2] for r in rects)
            r = max(r[3] for r in rects)

            # Only include if dimensions make sense (at least 3x3 after merging)
            if r - t + 1 >= 3 and l - b + 1 >= 3:
                final_rects.add((t, l, b, r))

    print(f"Found {len(final_rects)} final rectangles")
    for rect in list(final_rects)[:10]:
        t, l, b, r = rect
        print(f"  Rows {t}-{b}, Cols {l}-{r}: size {(b-t+1)*(r-l+1)}")

    # Fill in rectangles
    for t, l, b, r in final_rects:
        for row in range(t, b+1):
            for col in range(l, r+1):
                if 0 <= row < H and 0 <= col < W:
                    output[row][col] = 8

    return output

