def flood_fill_interior(grid):
    """Find all enclosed regions (not reachable from edges without crossing 8s)"""
    H, W = len(grid), len(grid[0])
    exterior = set()

    # Start from edge cells
    stack = []
    for c in range(W):
        if grid[0][c] == 0:
            stack.append((0, c))
        if grid[H-1][c] == 0:
            stack.append((H-1, c))
    for r in range(H):
        if grid[r][0] == 0:
            stack.append((r, 0))
        if grid[r][W-1] == 0:
            stack.append((r, W-1))

    while stack:
        r, c = stack.pop()
        if (r, c) in exterior or r < 0 or r >= H or c < 0 or c >= W or grid[r][c] == 8:
            continue
        exterior.add((r, c))
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            stack.append((r+dr, c+dc))

    return exterior

